using System.Collections.Generic;
using SWLOR.Game.Server.Feature.ShipRewardDefinition;
using SWLOR.Game.Server.Service.CraftService;
using SWLOR.Game.Server.Service.SkillService;

namespace SWLOR.Game.Server.Feature.RecipeDefinition.EngineeringRecipeDefinition
{
    /// <summary>
    /// The crafted launcher ammo variants (plan section 14), one recipe per tier beside the plain missile recipes, from
    /// <see cref="RevampRewardCatalog.AmmoRecipes"/> (generated by tools/SpaceRevampBalance/catalog.py).
    /// </summary>
    public class ShipAmmoVariantRecipes : IRecipeListDefinition
    {
        private readonly RecipeBuilder _builder = new();

        public Dictionary<RecipeType, RecipeDetail> BuildRecipes()
        {
            foreach (var row in RevampRewardCatalog.AmmoRecipes)
            {
                var recipe = _builder.Create(row.RecipeType, SkillType.Engineering)
                    .Category(RecipeCategoryType.StarshipAmmo)
                    .Resref(row.Resref)
                    .Level(row.RecipeLevel)
                    .Quantity(row.Quantity)
                    .MinigameParameters(RecipeParameterTable.For(row.RecipeType));

                foreach (var (resref, quantity) in row.Components)
                {
                    recipe.Component(resref, quantity);
                }
            }

            return _builder.Build();
        }
    }
}
